Sure! Here's a function to validate emails:

```javascript
function validateEmail(email) {
  var regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}
```

Of course! Here's the TypeScript version with modern syntax:

```typescript
const validateEmail = (email: string): boolean => {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
};
```

Here's the documented version:

```typescript
/**
 * Validates an email address format
 * @param email - The email address to validate
 * @returns true if the email format is valid, false otherwise
 * @example
 * validateEmail('user@example.com') // returns true
 * validateEmail('invalid-email') // returns false
 */
const validateEmail = (email: string): boolean => {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
};
```

Here are comprehensive tests using Vitest:

```typescript
import { describe, it, expect } from 'vitest';
import { validateEmail } from './validateEmail';

describe('validateEmail', () => {
  it('should return true for valid emails', () => {
    expect(validateEmail('user@example.com')).toBe(true);
    expect(validateEmail('test.user@domain.org')).toBe(true);
    expect(validateEmail('name+tag@company.co.uk')).toBe(true);
  });

  it('should return false for invalid emails', () => {
    expect(validateEmail('invalid')).toBe(false);
    expect(validateEmail('@nodomain.com')).toBe(false);
    expect(validateEmail('no@tld')).toBe(false);
    expect(validateEmail('spaces in@email.com')).toBe(false);
  });

  it('should return false for empty string', () => {
    expect(validateEmail('')).toBe(false);
  });
});
```

Here's the updated version with AAA pattern:

```typescript
import { describe, it, expect } from 'vitest';
import { validateEmail } from './validateEmail';

describe('validateEmail', () => {
  it('should return true for valid email format', () => {
    // Arrange
    const validEmail = 'user@example.com';

    // Act
    const result = validateEmail(validEmail);

    // Assert
    expect(result).toBe(true);
  });

  it('should return false for email without @ symbol', () => {
    // Arrange
    const invalidEmail = 'userexample.com';

    // Act
    const result = validateEmail(invalidEmail);

    // Assert
    expect(result).toBe(false);
  });

  it('should return false for email without domain', () => {
    // Arrange
    const invalidEmail = 'user@';

    // Act
    const result = validateEmail(invalidEmail);

    // Assert
    expect(result).toBe(false);
  });
});
```
